message.content:
{
  "description": "The creature is a large quadrupedal animal shown in right-facing profile against a plain light background. It has the overall body shape, dense brown fur, head shape, and clawed paws of a bear, but most of its dorsal surface, neck, sides, and outer limbs are covered in glossy, dark brown to black overlapping segmented armor plates that resemble the exoskeleton of an isopod or pill bug. The armor forms a continuous carapace over the back from the neck to the rear, with separate plated sections over the shoulders, hips, and limbs, and lighter tan segmented plating visible on the underside and inner legs. A single large, curved, glossy black horn with small tooth-like notches along its inner edge projects from a helmet-like plate on top of the head. The animal stands on four thick legs with broad paws, and has a short, tapered, segmented tail at the rear.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with dense brown fur, a lighter tan muzzle, a large dark nose, small brown eyes, and fine whiskers on the muzzle",
      "where": "at the front of the body, facing to the right, with the lower face and throat exposed and the top covered by a dark plate"
    },
    {
      "part": "horns",
      "looks_like": "a single long, glossy black, sharply curved horn with a pointed tip and two small tooth-like projections on its inner curve, resembling a rhinoceros beetle horn",
      "where": "arising from the center of the dark plate on top of the head and curving upward and backward then forward over the head"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, furry brown ears with dense fur",
      "where": "on top of the head on either side of the horn base, protruding through openings in the head and neck plates"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular legs with brown fur visible between and beneath overlapping glossy dark armored plates that cover the outer upper and lower segments; the inner and underside surfaces show lighter tan segmented plating",
      "where": "under the body, two forelegs under the chest and two hindlegs under the hips, supporting the body in a standing posture"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with brown fur on top and long, curved, dark claws on the toes",
      "where": "at the bottom end of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a short, narrow, tapered tail made of small overlapping dark segments ending in a point",
      "where": "extending from the rear end of the body at the back of the armored carapace"
    },
    {
      "part": "plates",
      "looks_like": "numerous glossy, dark brown-black, overlapping, hard-looking segmented plates forming a carapace over the back, with larger smooth plates over the shoulders and hips and smaller banded plates around the neck, sides, and limbs; the belly and inner legs have lighter tan, ridged, segmented plating",
      "where": "covering the top of the head as a helmet, the back from neck to tail, the sides of the torso, the front and sides of the neck, and the outer surfaces of all four legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros beetle",
    "pill bug"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
